def choose_move(observation):
    # Defensive extraction of observation fields
    grid = observation.get('grid', [])
    own_pos = observation.get('position', (0,0))
    resource_positions = observation.get('resources', [])
    opponent_positions = observation.get('opponents', [])
    territory_control = observation.get('territory', [])
    mode = observation.get('mode', '')

    # Initialize movement vector
    dx, dy = 0, 0

    # Helper functions
    def in_bounds(pos):
        x, y = pos
        return 0 <= x < len(grid) and 0 <= y < len(grid[0])

    def is_cell_free(pos):
        if not in_bounds(pos):
            return False
        x, y = pos
        return grid[x][y] == 0

    def get_adjacent(pos):
        x, y = pos
        adj = [ (x+1, y), (x-1, y), (x, y+1), (x, y-1) ]
        return [p for p in adj if in_bounds(p)]

    def move_towards(target_pos):
        cx, cy = own_pos
        tx, ty = target_pos
        dx_candidate = 0
        dy_candidate = 0
        if tx > cx:
            dx_candidate = 1
        elif tx < cx:
            dx_candidate = -1
        if ty > cy:
            dy_candidate = 1
        elif ty < cy:
            dy_candidate = -1
        # Prioritize directions
        directions = []
        if dx_candidate != 0:
            directions.append( (cx + dx_candidate, cy) )
        if dy_candidate != 0:
            directions.append( (cx, cy + dy_candidate) )
        # Filter valid moves
        for new_pos in directions:
            if is_cell_free(new_pos):
                return new_pos
        # If preferred moves blocked, try other adjacent cells
        for adj in get_adjacent(own_pos):
            if is_cell_free(adj):
                return adj
        return own_pos  # No move possible

    # Determine action based on mode
    if mode == 'resource_collection':
        # If resources available, move towards the closest one
        if resource_positions:
            # Find closest resource
            def dist(a, b):
                return abs(a[0]-b[0]) + abs(a[1]-b[1])
            target = min(resource_positions, key=lambda p: dist(own_pos, p))
            new_pos = move_towards(target)
            dx, dy = new_pos[0] - own_pos[0], new_pos[1] - own_pos[1]
            if dx not in [-1, 0, 1]:
                dx = 0
            if dy not in [-1, 0, 1]:
                dy = 0
            return [dx, dy]
        else:
            # No resources, move randomly or stay
            return [0,0]
    elif mode == 'pursuit_evasion':
        # If opponents present, pursue the closest one
        if opponent_positions:
            def dist(a, b):
                return abs(a[0]-b[0]) + abs(a[1]-b[1])
            target = min(opponent_positions, key=lambda p: dist(own_pos, p))
            new_pos = move_towards(target)
            dx, dy = new_pos[0] - own_pos[0], new_pos[1] - own_pos[1]
            if dx not in [-1, 0, 1]:
                dx = 0
            if dy not in [-1, 0, 1]:
                dy = 0
            return [dx, dy]
        else:
            # No opponents, default to no move
            return [0,0]
    elif mode == 'territory_control':
        # Move towards unclaimed territory if known
        # Assume territory_control is a grid matching the main grid
        # and unclaimed territory marked as 0
        # Find nearest unclaimed cell
        min_dist = float('inf')
        target_cell = None
        for x in range(len(grid)):
            for y in range(len(grid[0])):
                if territory_control and territory_control[x][y] == 0:
                    dist_curr = abs(own_pos[0]-x) + abs(own_pos[1]-y)
                    if dist_curr < min_dist:
                        min_dist = dist_curr
                        target_cell = (x, y)
        if target_cell:
            new_pos = move_towards(target_cell)
            dx, dy = new_pos[0] - own_pos[0], new_pos[1] - own_pos[1]
            if dx not in [-1, 0, 1]:
                dx = 0
            if dy not in [-1, 0, 1]:
                dy = 0
            return [dx, dy]
        else:
            # No unclaimed territory, stay
            return [0,0]
    else:
        # Default behavior: stay
        return [0,0]
